def apply(hou, asset_path='/obj/StreetBuilding_DEV', save=False):
    if save:
        raise ValueError('Persistence belongs to VerifyFull, not the patch')
    asset=hou.node(asset_path)
    if asset is None or asset.type().name()!='pcgbike::StreetBuilding::1.0':
        raise RuntimeError('Current StreetBuilding instance changed')
    node=asset.node('StreetBuildingCore/ALLOCATE_FACADE_CAPACITY')
    parm=node.parm('snippet')
    before=parm.eval()
    digest=hashlib.sha256(before.encode('utf-8')).hexdigest()
    if digest==RESULT:
        return {'status':'UNCHANGED','node':node.path(),'save':False}
    if digest!=EXPECTED:
        raise RuntimeError('Allocator precondition hash mismatch: '+digest)
    try:
        parm.set(SOURCE)
        node.cook(force=True)
        if node.errors() or node.warnings():
            raise RuntimeError('Allocator diagnostics: '+str((node.errors(),node.warnings())))
    except Exception:
        parm.set(before)
        raise
    return {'status':'APPLIED','node':node.path(),'sha256':RESULT,'save':False}
